head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > headerMergeSplit]<br/>Header Column 의 ID 를 사용하여 Header Column 의 동적 병합을 해제합니다.",
    "validation" : [
        "headerID(필수) 파라미터로 병합을 해제하려는 Header Column 의 ID 를 설정합니다. (병합된 영역 내의 Header Column 중 하나)",        
        "병합 해제의 성공 여부를 true/false 로 반환하며, 병합 영역이 아닌 경우 false 를 반환하고 병합 해제가 실행되지 않습니다.",
        "headerMerge() 메소드로 동적 병합한 Header 영역만 해제할 수 있습니다."
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 안내 라벨 생성 (가장 먼저)
    $c.gcm.createLabel('label="Header Column 은 column1 ~ column6 이며 디자인 병합이 없는 평범한 헤더입니다. headerMerge 로 동적 병합한 영역만 headerMergeSplit 으로 해제할 수 있습니다."', '', 'label1');

    // 기존 dataList 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }

    // grp_comp 영역 / 네임스페이스 확인
    let grp_comp = $c.gcm.getTestGroup();
    let strNameSpace = $c.gcm.getNameSpace();

    // DataList 생성 (col1~col6) 후 데이터 4행 setJSON 으로 채우고 gridView 에 바인딩
    let strData = '';
    strData += '<w2:dataList ' + strNameSpace + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strData += '<w2:columnInfo>';
    for (let c = 1; c <= 6; c++) {
        strData += '<w2:column id="col' + c + '" name="name' + c + '" dataType="text"></w2:column>';
    }
    strData += '</w2:columnInfo>';
    strData += '<w2:data use="true"></w2:data>';
    strData += '</w2:dataList>';
    $p.data.create(strData);

    let jsonData = [];
    for (let rIdx = 1; rIdx <= 4; rIdx++) {
        jsonData.push({ col1: "v" + rIdx + "_1", col2: "v" + rIdx + "_2", col3: "v" + rIdx + "_3", col4: "v" + rIdx + "_4", col5: "v" + rIdx + "_5", col6: "v" + rIdx + "_6" });
    }
    dlt_bind.setJSON(jsonData);

    // Header Column 6개(column1~column6) + Body 6컬럼 동적 생성 (디자인 병합 없음)
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' checkAllType="false" dataList="data:dlt_bind" id="" style="width:600px;height:260px;">';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="90" inputType="text" id="column1" value="name1"></w2:column>';
    strTarget += '<w2:column width="90" inputType="text" id="column2" value="name2"></w2:column>';
    strTarget += '<w2:column width="90" inputType="text" id="column3" value="name3"></w2:column>';
    strTarget += '<w2:column width="90" inputType="text" id="column4" value="name4"></w2:column>';
    strTarget += '<w2:column width="90" inputType="text" id="column5" value="name5"></w2:column>';
    strTarget += '<w2:column width="90" inputType="text" id="column6" value="name6"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="90" inputType="text" id="col1" value=""></w2:column>';
    strTarget += '<w2:column width="90" inputType="text" id="col2" value=""></w2:column>';
    strTarget += '<w2:column width="90" inputType="text" id="col3" value=""></w2:column>';
    strTarget += '<w2:column width="90" inputType="text" id="col4" value=""></w2:column>';
    strTarget += '<w2:column width="90" inputType="text" id="col5" value=""></w2:column>';
    strTarget += '<w2:column width="90" inputType="text" id="col6" value=""></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate("target1", "gridView", strTarget, grp_comp);
}



// 특정 Header th 의 colspan / 화면 표시 Header th 개수를 DOM 으로 확인 출력
scwin.printHeaderState = function (headerID) {
    let th = document.querySelector("th[data-header_id='" + headerID + "'], th[header_id='" + headerID + "']");
    if (th) {
        wf_body_bottom.getObj("scwin").setReturnValue("[" + headerID + " th] colspan : " + (th.getAttribute("colspan") || "없음") + ", rowspan : " + (th.getAttribute("rowspan") || "없음"));
    }
    // 화면에 표시되는(display none 아닌) Header th 개수 — 병합 시 줄고, 해제 시 다시 늘어남
    let visibleThCnt = 0;
    let allTh = document.querySelectorAll("th[data-header_id], th[header_id]");
    for (let i = 0; i < allTh.length; i++) {
        if (allTh[i].style.display !== "none") visibleThCnt++;
    }
    wf_body_bottom.getObj("scwin").setReturnValue("화면 표시 Header th 개수 : " + visibleThCnt + " (병합 전 6개)");
}



// (사전조건) headerMerge 로 동적 병합 생성 — split 검증의 선행 단계 (headerMergeSplit 검증 대상 아님)
scwin.btn_headerMerge_onclick = function () {
    // 기존 동적 헤더 병합 초기화 후 column2 ~ column4 직사각형 병합 (colspan 3)
    target1.headerMergeClear();
    let result = target1.headerMerge("column2", "column4");
    wf_body_bottom.getObj("scwin").setReturnValue("[사전조건] headerMerge('column2', 'column4') : " + result);
    scwin.printHeaderState("column2");
}



// (validation #1, #3 true, #4) 병합 영역 내 Header ID 로 동적 병합 해제 → true + colspan 해제
scwin.btn_headerMergeSplit_onclick = function () {
    let headerID = par_headerID.getValue();

    let result = target1.headerMergeSplit(headerID);
    wf_body_bottom.getObj("scwin").setReturnValue("headerMergeSplit('" + headerID + "') : " + result);

    // 병합이 해제되면 해당 영역 시작 th 의 colspan 이 해제(없음/1)되고 화면 표시 th 개수가 다시 6개로 복원됨
    scwin.printHeaderState("column2");
}



// (validation #3 false 케이스) 병합 영역이 아닌 Header ID 로 해제 시도 → 가이드상 false 반환 + 미실행
scwin.btn_headerMergeSplit_false_onclick = function () {
    // 사전조건: column2 ~ column4 동적 병합
    target1.headerMergeClear();
    target1.headerMerge("column2", "column4");
    scwin.printHeaderState("column2");

    // column6 은 동적 병합되지 않은 영역 → 가이드상 병합 영역이 아니므로 false + 병합 해제 미실행
    // 실제 엔진: 반환값은 true 이나 병합 해제는 미실행(column2 colspan 유지) — 가이드와 반환값 불일치
    let result = target1.headerMergeSplit("column6");
    wf_body_bottom.getObj("scwin").setReturnValue("headerMergeSplit('column6') : " + result + " (병합 영역 아님 → 미실행)");
    // column2 병합이 그대로 유지되는지로 미실행 확인
    scwin.printHeaderState("column2");
}
